class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> result = new ArrayList<>();
        backtrack(candidates, 0, target, new ArrayList<>(), result);
        return result;
    }

    private void backtrack(int[] candidates, int start, int remaining,
                           List<Integer> path, List<List<Integer>> result) {
        if (remaining == 0) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (int j = start; j < candidates.length; j++) {
            if (candidates[j] > remaining) break;       // sorted -> prune rest
            path.add(candidates[j]);
            backtrack(candidates, j, remaining - candidates[j], path, result); // reuse allowed
            path.remove(path.size() - 1);
        }
    }
}

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        backtrack(new StringBuilder(), 0, 0, n, result);
        return result;
    }

    private void backtrack(StringBuilder path, int openCount, int closeCount,
                           int n, List<String> result) {
        if (path.length() == 2 * n) {
            result.add(path.toString());
            return;
        }
        if (openCount < n) {
            path.append('(');
            backtrack(path, openCount + 1, closeCount, n, result);
            path.deleteCharAt(path.length() - 1);   // un-choose
        }
        if (closeCount < openCount) {
            path.append(')');
            backtrack(path, openCount, closeCount + 1, n, result);
            path.deleteCharAt(path.length() - 1);   // un-choose
        }
    }
}

