class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] r : board) Arrays.fill(r, '.');
        boolean[] cols  = new boolean[n];
        boolean[] diag1 = new boolean[2 * n - 1];   // row + col
        boolean[] diag2 = new boolean[2 * n - 1];   // row - col + n - 1
        backtrack(board, 0, cols, diag1, diag2, result);
        return result;
    }

    private void backtrack(char[][] board, int row, boolean[] cols,
                           boolean[] diag1, boolean[] diag2,
                           List<List<String>> result) {
        int n = board.length;
        if (row == n) {
            result.add(buildBoard(board));
            return;
        }
        for (int col = 0; col < n; col++) {
            int d1 = row + col, d2 = row - col + n - 1;
            if (cols[col] || diag1[d1] || diag2[d2]) continue;   // prune
            board[row][col] = 'Q';
            cols[col] = diag1[d1] = diag2[d2] = true;
            backtrack(board, row + 1, cols, diag1, diag2, result);
            board[row][col] = '.';                                // un-choose
            cols[col] = diag1[d1] = diag2[d2] = false;
        }
    }

    private List<String> buildBoard(char[][] board) {
        List<String> rows = new ArrayList<>();
        for (char[] r : board) rows.add(new String(r));
        return rows;
    }
}

class Solution {
    public void solveSudoku(char[][] board) {
        backtrack(board);
    }

    private boolean backtrack(char[][] board) {
        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] != '.') continue;      // find next empty cell
                for (char digit = '1'; digit <= '9'; digit++) {
                    if (isValid(board, row, col, digit)) {
                        board[row][col] = digit;             // choose
                        if (backtrack(board)) return true;   // explore
                        board[row][col] = '.';               // un-choose
                    }
                }
                return false;   // no digit works here -> dead end, backtrack up
            }
        }
        return true;  // no empty cells left -> solved
    }

    private boolean isValid(char[][] board, int row, int col, char digit) {
        int boxRow = 3 * (row / 3), boxCol = 3 * (col / 3);
        for (int i = 0; i < 9; i++) {
            if (board[row][i] == digit) return false;                 // row check
            if (board[i][col] == digit) return false;                 // column check
            if (board[boxRow + i / 3][boxCol + i % 3] == digit) return false; // box check
        }
        return true;
    }
}

