boolean dfs(char[][] board, String word, int r, int c, int idx) {
    if (idx == word.length()) return true;               // matched full word
    if (r < 0 || c < 0 || r >= board.length || c >= board[0].length
        || board[r][c] != word.charAt(idx)) return false; // out of bounds or mismatch

    char temp = board[r][c];
    board[r][c] = '#';                                     // mark visited (choose)
    boolean found = dfs(board, word, r + 1, c, idx + 1)
                 || dfs(board, word, r - 1, c, idx + 1)
                 || dfs(board, word, r, c + 1, idx + 1)
                 || dfs(board, word, r, c - 1, idx + 1);
    board[r][c] = temp;                                    // un-mark (un-choose)
    return found;
}

