void backtrack(String s, int start, List<String> path, List<List<String>> result) {
    if (start == s.length()) {
        result.add(new ArrayList<>(path));
        return;
    }
    for (int end = start + 1; end <= s.length(); end++) {
        String piece = s.substring(start, end);
        if (!isValidPiece(piece)) continue;    // pruning check (e.g. palindrome)
        path.add(piece);                        // choose this cut
        backtrack(s, end, path, result);        // explore remainder
        path.remove(path.size() - 1);           // un-choose
    }
}

