class Solution {
    public List<List<String>> partition(String s) {
        int n = s.length();
        boolean[][] isPalin = new boolean[n][n];
        for (int end = 0; end < n; end++) {
            for (int start = end; start >= 0; start--) {
                if (s.charAt(start) == s.charAt(end)
                    && (end - start <= 2 || isPalin[start + 1][end - 1])) {
                    isPalin[start][end] = true;
                }
            }
        }

        List<List<String>> result = new ArrayList<>();
        backtrack(s, 0, isPalin, new ArrayList<>(), result);
        return result;
    }

    private void backtrack(String s, int start, boolean[][] isPalin,
                           List<String> path, List<List<String>> result) {
        if (start == s.length()) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (int end = start; end < s.length(); end++) {
            if (!isPalin[start][end]) continue;            // pruning check, O(1) lookup
            path.add(s.substring(start, end + 1));         // choose this cut
            backtrack(s, end + 1, isPalin, path, result);  // explore remainder
            path.remove(path.size() - 1);                  // un-choose
        }
    }
}
